// Suggestions the records generated by fixed rules. Adopting one is the owner's call: nothing changes until the button is pressed,
// and it can be taken back. The main process records the choice; the page shows the summary it returns.
import { useState } from 'react';
import type { DashboardSuggestion } from '../../shared/dashboard-types';
import { t } from '../../shared/i18n';
import { weightChange } from './format';
import { Empty } from './Panel';

type Decide = (id: string, state: DashboardSuggestion['state']) => Promise<string | null>;

// What the status line says after a decision. An adopted weight reaches the lead through the sessions opened afterwards.
export const decisionNote = (next: DashboardSuggestion['state'], item: Pick<DashboardSuggestion, 'kind' | 'title'>, error: string | null) =>
  error ? t('没有保存：{message}', { message: error })
    : next === 'adopted' ? (item.kind === 'weight' ? t('已采纳「{title}」，记在本机；之后新开的主编排会话会按它分工。', { title: item.title }) : t('已采纳「{title}」，记在本机。', { title: item.title }))
      : next === 'dismissed' ? t('已标为不采纳「{title}」。', { title: item.title }) : t('已撤销「{title}」。', { title: item.title });

export function Suggestions({ suggestions, decide }: { suggestions: DashboardSuggestion[]; decide: Decide }) {
  const [busy, setBusy] = useState<string | null>(null), [note, setNote] = useState('');
  const run = async (item: DashboardSuggestion, next: DashboardSuggestion['state']) => {
    setBusy(item.id);
    const error = await decide(item.id, next);
    setBusy(null);
    setNote(decisionNote(next, item, error));
  };
  const tags = { adopted: t('已采纳 ✓'), dismissed: t('不采纳'), open: '' };
  // The first button keeps its place when a suggestion changes state (采纳 becomes 撤销), so keyboard focus stays on it.
  return <>
    {suggestions.length === 0 ? <Empty>{t('这段时间没有建议')}</Empty> : <div className="advice">
      {suggestions.map(item => <div key={item.id} className="advice-item">
        <span className="advice-head"><span className="tag">{item.kind === 'weight' ? t('路由权重') : t('协作机制')}</span><strong>{item.title}</strong>{tags[item.state] && <span className="tag">{tags[item.state]}</span>}</span>
        <span className="advice-actions">
          <button type="button" className="button" disabled={busy === item.id} onClick={() => run(item, item.state === 'open' ? 'adopted' : 'open')}>{item.state === 'open' ? t('采纳') : t('撤销')}</button>
          {item.state === 'open' && <button type="button" className="button" disabled={busy === item.id} onClick={() => run(item, 'dismissed')}>{t('不采纳')}</button>}
        </span>
        <p>{item.text}{item.weight && <span className="weight">{weightChange(item.weight)}</span>}</p>
      </div>)}
    </div>}
    <p className="advice-note" role="status">{note}</p>
  </>;
}
